<?php defined('ABSPATH') || exit; get_header(); global $wp_query; $is_category = is_tax('bilyan_category'); $current_term = $is_category ? get_queried_object() : null; ?>
<div class="container page-top <?php echo $is_category ? 'category-page-top' : ''; ?>"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a><span>/</span><span>Shop</span><?php if ($is_category): ?><span>/</span><span><?php echo esc_html($current_term->name); ?></span><?php endif; ?></div><?php if ($is_category): ?><div class="category-hero"><div><span class="eyebrow">SHOP THIS CATEGORY</span><h1><?php echo esc_html($current_term->name); ?></h1><p><?php echo esc_html($current_term->description ?: 'Thoughtfully chosen finds for your everyday.'); ?></p><span class="category-count"><?php echo esc_html($current_term->count); ?> products</span></div><div class="category-hero-image"><img src="<?php echo esc_url(bilyan_category_image($current_term)); ?>" alt="<?php echo esc_attr($current_term->name); ?>"></div></div><?php else: ?><span class="eyebrow">FIND SOMETHING YOU LOVE</span><h1><?php echo is_search() ? 'Results for “' . esc_html(get_search_query()) . '”' : 'The everyday collection'; ?></h1><p>Good finds for your home, your style, and everything in between.</p><?php endif; ?></div>
<?php if (!$is_category && !is_search()): $terms_top = get_terms(['taxonomy' => 'bilyan_category', 'hide_empty' => false]); if (!is_wp_error($terms_top) && $terms_top): ?><section class="container shop-categories"><div class="section-heading"><div><span class="eyebrow">BROWSE YOUR WAY</span><h2>Shop by category</h2></div><span class="category-intro">Start with what you need. Discover the rest as you go.</span></div><div class="shop-category-grid"><?php foreach ($terms_top as $term): ?><a class="shop-category-card" href="<?php echo esc_url(get_term_link($term)); ?>"><span class="shop-category-image"><img loading="lazy" src="<?php echo esc_url(bilyan_category_image($term)); ?>" alt="<?php echo esc_attr($term->name); ?>"></span><span class="shop-category-copy"><strong><?php echo esc_html($term->name); ?></strong><small><?php echo esc_html($term->count); ?> products</small></span><span class="shop-category-arrow"><?php echo bilyan_icon('arrow'); ?></span></a><?php endforeach; ?></div></section><?php endif; endif; ?>
<div class="container catalog-layout"><aside class="catalog-sidebar"><h2>Categories</h2><a class="category-filter <?php echo !$is_category ? 'active' : ''; ?>" href="<?php echo esc_url(get_post_type_archive_link('bilyan_product')); ?>">All products <?php echo bilyan_icon('arrow'); ?></a><?php $terms = get_terms(['taxonomy' => 'bilyan_category', 'hide_empty' => false]); if (!is_wp_error($terms)) foreach ($terms as $term) echo '<a class="category-filter ' . (is_tax('bilyan_category', $term->term_id) ? 'active' : '') . '" href="' . esc_url(get_term_link($term)) . '">' . esc_html($term->name) . '<span>' . esc_html($term->count) . '</span></a>'; ?><div class="sidebar-help"><?php echo bilyan_icon('headphones'); ?><h3>Need a hand?</h3><p>Let’s help you find what you’re looking for.</p><a class="text-link" href="<?php echo esc_url(bilyan_page_url('contact')); ?>">Contact us →</a></div></aside><section class="catalog-results" aria-label="Products"><div class="catalog-toolbar"><span><?php echo esc_html($wp_query->found_posts); ?> products</span><form method="get"><label for="sort">Sort by</label><?php if (is_search()): ?><input type="hidden" name="s" value="<?php echo esc_attr(get_search_query()); ?>"><input type="hidden" name="post_type" value="bilyan_product"><?php endif; ?><select name="sort" id="sort"><option value="latest">Newest first</option><option value="name" <?php selected(isset($_GET['sort']) && $_GET['sort'] === 'name'); ?>>Name: A–Z</option><option value="oldest" <?php selected(isset($_GET['sort']) && $_GET['sort'] === 'oldest'); ?>>Oldest first</option></select><button class="sort-submit">Apply</button></form></div><div class="product-grid catalog-grid"><?php if (have_posts()) { while (have_posts()) { the_post(); bilyan_product_card(get_the_ID()); } } else { ?><div class="empty-state"><h2>No products found</h2><p>Try a different search or browse another category.</p><a class="button" href="<?php echo esc_url(get_post_type_archive_link('bilyan_product')); ?>">Browse all products</a></div><?php } ?></div><div class="pagination"><?php the_posts_pagination(['mid_size' => 1, 'prev_text' => '← Previous', 'next_text' => 'Next →']); ?></div></section></div>
<?php get_footer(); ?>
